return {
  json: {
    ...$input.item.json,
    _pdv: 'Norte - Alberdi 608 bis',
    _apiKey: 'PEGAR_API_KEY_NORTE',
    _documentId: 'PEGAR_ID_PLANILLA_NORTE',
    _rowNumber: $input.item.json.row_number,
  },
}

// Punto único por donde pasan las tres planillas: de acá para abajo
// la lógica es la misma para los tres locales.
const row = $input.item.json
const tipo = String(row['Tipo'] || '').trim().toUpperCase()

let _error = null
if (!['VENTA', 'INGRESO', 'AJUSTE'].includes(tipo)) {
  _error = `Tipo inválido: "${row['Tipo'] ?? ''}" (poné VENTA, INGRESO o AJUSTE)`
} else if (!String(row['Producto'] || '').trim()) {
  _error = 'Falta el nombre del producto'
} else if (!String(row['Talle'] || '').trim()) {
  _error = 'Falta el talle'
}

return { json: { ...row, tipoPath: tipo ? tipo.toLowerCase() : '', _error } }

const item = $('Validar fila').item.json
if (item._error) return { json: { ...item } }

const productos = ($input.item.json && $input.item.json.data) || []
const nombreBuscado = String(item['Producto'] || '').trim().toLowerCase()
// Preferimos la coincidencia exacta; si no hay, el primer resultado de la búsqueda.
const producto = productos.find(p => p.nombre.trim().toLowerCase() === nombreBuscado) || productos[0]
if (!producto) return { json: { ...item, _error: `Producto no encontrado: "${item['Producto']}"` } }

const body = { productoId: producto.id, talle: String(item['Talle'] || '').trim() }
if (item['Color']) body.color = String(item['Color']).trim()

if (item.tipoPath === 'ajuste') {
  body.cantidadFinal = Number(item['Cantidad final (solo AJUSTE)'])
  body.nota = item['Nota'] || ''
} else {
  body.cantidad = Number(item['Cantidad'])
  if (item['Nota']) body.nota = item['Nota']
}

return { json: { ...item, body } }

const ctx = $('Preparar estado').item.json
const f = ctx.fila
const filas = $input.item.json.values || []

const igual = (a, b) => String(a ?? '').trim() === String(b ?? '').trim()

// Buscamos de abajo hacia arriba: lo recién agregado está al final.
// Solo miramos filas con Estado vacío, así nunca pisamos una ya resuelta.
let encontrada = null
for (let i = filas.length - 1; i >= 1; i--) {
  const r = filas[i]
  const estadoVacio = !String(r[8] ?? '').trim()
  if (!estadoVacio) continue
  if (igual(r[1], f['Tipo']) && igual(r[2], f['Producto']) && igual(r[3], f['Talle'])
      && igual(r[4], f['Color']) && igual(r[5], f['Cantidad']) && igual(r[7], f['Nota'])) {
    encontrada = i + 1 // la API es 1-based
    break
  }
}

if (!encontrada) throw new Error('No pude ubicar la fila para escribirle el estado')
return { json: { documentId: ctx.documentId, estado: ctx.estado, row_number: encontrada } }
